-- Mod-authored victory and defeat screen descriptions, ja_JP overlay.
-- Baseline in CivVAccess_VictoryDescStrings_en_US.lua.
CivVAccess_Strings = CivVAccess_Strings or {}

CivVAccess_Strings["TXT_KEY_CIVVACCESS_VICTORYDESC_MISSING"] = "この画面の説明はありません."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_VICTORYDESC_VICTORY_CULTURAL"] =
    "暗い木に陰を落とされた草の生い茂る丘の上から, 二つの人影がシルエットとなって腰かけ, 金色に輝く都市を見渡している. その下では群衆が, 台座の上に立つ古典様式の彫像に挟まれた石造りのアーチ橋を渡り, その奥には丸屋根の大広間がそびえている. 公園地帯の向こうでは, 街並みが細い未来的な塔へと立ち上がり, 琥珀色の靄の中へ溶けていく. 芝生には人々が点在し, 子供たちは糸で高く揚がった凧の下を駆け回り, 一人は黄色いパラソルの下を歩き, 遠い水面には靄を通して白い帆が見える. 場面全体が温かな金色の光に浸され, 半ば遅い午後で半ば夢のようであり, 空には鳥が散らばっている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_VICTORYDESC_VICTORY_DIPLOMATIC"] =
    "国際連合本部の高い白い石板の前, 緑の芝生の上で行われる式典. 前景では群衆がこちらに背を向けて立ち, 多くの国々のスーツ, ローブ, 頭巾を身に着け, 右手では三脚に据えたカメラで撮影する撮影技師がいる. 芝生を囲む旗竿には数十の国旗が掲げられ, その中にはアメリカ合衆国とメキシコの旗が見分けられる. 中央では大きな石の地球儀が, 枝を広げた木々の下の四角い台座の上に据えられ, その大陸が浮き彫りで盛り上がっている. その前には, さまざまな国の民族衣装をまとった子供たちの列が待っている. 青い服の女性が身をかがめ, 手を伸ばす黄色いワンピースの幼い少女に何かを手渡そうとしている. 赤と白の花壇が画面の下端の静かな池を縁取り, 柔らかな灰色の昼の光がすべてを均一に照らしている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_VICTORYDESC_VICTORY_DOMINATION"] =
    "金, オリーブ, 赤のポスター調の色彩で描かれた戦勝パレード. 右の前景では, 肩に金の組み紐を付けた白い礼装の若い士官が, 空一面にはためく巨大な赤い旗の竿を握り, その鍔付きの帽子は赤い帯と金の徽章で飾られている. その背後では, 揃いの白い軍服を着た兵士たちの列が, 銃剣を付けた小銃を肩に立てて立ち, 隊列からさらに多くの赤い旗が立ち上がっている. パレードの上方には, 高い台座の頂に, 歩み出る馬に乗った指揮官の青銅像が立ち, その背後には大きな丸屋根の議事堂が建っている. 細い赤い幟が, 輝く黄緑色の空をリボンのように横切ってたなびき, 暗い糸杉と霞んだ山々が遠景を閉じている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_VICTORYDESC_VICTORY_SPACE_RACE"] =
    "深宇宙, 巨大な軌道ステーションを下から見上げている. その暗い船体は画面の上端いっぱいに広がり, 下面には背の高い暖色に灯る窓と緑に光る格納庫が列を成している. 金属の表面を蒸気の筋が漂っていく. 平らな格子状の太陽電池板が, 桁組みの腕木に支えられて船体から広がり, 長いパネル張りのトラス塔がその遠端から画面の右側へと垂れ下がっている. その下では, 惑星の夜の側が深い菫色とワイン色をたたえて遠くへ広がり, その地平線が場面の下端を弧を描いて横切る. 太陽がちょうどその地平線の上に昇りかけ, 白金色の閃光となって曲線に沿ったバラ色とクリーム色の雲の帯を照らしている. 前景では, 一隻の翼を持つ船が長く輝く青緑色の航跡を引いて暗闇を横切り, より小さな機影が星々を背景に遠くで緑と橙色にきらめいている."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_VICTORYDESC_VICTORY_TIME"] =
    "ゲーム自身の表紙絵が画面いっぱいに拡大されている. 古いセピア色の地図を継ぎ合わせた地球儀が画面を占め, その上には Sid Meier's Civilization の題字が, 巨大な真鍮のローマ数字の五を貫いて, 磨かれた金属の浮き彫り文字で横切っている. 左上には使い古されたフィンランドの郵便切手が貼られ, 装飾を施した馬に乗る騎手がカレワラの叙事詩を記念している. その周りには消印が薄く押されている. 地球儀の背後には青緑色に染めた紙のコラージュが広がり, 真鍮の子午線の輪が地球儀の下縁を弧を描いて巡り, 光は左上から差し込み, まるでランプの下に置かれた骨董品のようである."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_VICTORYDESC_DEFEAT"] =
    "砂漠の空の下の滅びた帝国. 巨大な石の彫像の頭部が砂の上に頬を伏せて横たわり, 目を閉じて顔は穏やかであり, その近くには折れた石の手が地中から伸び, 指を空に向けて曲げている. それを取り囲むように発掘現場が広がっている. 前景の土には塹壕が掘られ, 杭と鉄線の柵が連なり, 淡い色の服を着た一人が木製の階段台の上に立ち, 自らが調べる顔に比して小さく見える. 左手には荷役の動物が一頭待っている. 人気のない谷は, 点在する立ち残った断片を過ぎて, 地平線の頂の平らなメサへと続いている. すべては薄い青空の下で日に焼けた色と錆色に染まり, シェリーのオジマンディアスに歌われた寂しく平らな砂が遠くまで広がっている."
